61	
62	export function CtaBand() {
63	  return (
64	    <Reveal className="relative overflow-hidden rounded-3xl border border-white/[0.08] bg-navy-850/70 px-8 py-16 text-center backdrop-blur-md sm:px-16">
65	      <div
66	        className="pointer-events-none absolute inset-0 opacity-70"
67	        style={{
68	          backgroundImage:
69	            "radial-gradient(ellipse 60% 60% at 30% 0%, rgba(59,130,246,0.18), transparent), radial-gradient(ellipse 50% 60% at 80% 100%, rgba(138,112,251,0.18), transparent)",
70	        }}
71	      />
72	      <div className="relative">
73	        <h2 className="mx-auto max-w-2xl text-3xl font-bold tracking-tight sm:text-4xl">
74	          Deploy your first server in <span className="grad-text">under a minute</span>
75	        </h2>
76	        {/*
77	          This band renders on 22 pages, so its promise is the one prospects meet
78	          most. It used to read "No credit card required to get started. Spin up a
79	          VPS, break things, and only pay for what you keep running." — none of
80	          which survives contact with the product: free deploys are admin-only
81	          (`formData.get("free") === "1" && isAdmin`), a customer with no balance
82	          gets "Insufficient balance. Top up your wallet first.", and a term is
83	          paid up front rather than metered on what you keep running.
84	
85	          What is true is that the ACCOUNT is free and takes no card. Say that,
86	          and say plainly where the money starts.
87	        */}
88	        <p className="mx-auto mt-4 max-w-xl text-lg text-slate-400">
89	          Creating an account is free and takes no card details. You pay when you deploy — choose a
90	          billing term and pay from your wallet or by card at checkout.
91	        </p>
92	        <div className="mt-8 flex flex-wrap items-center justify-center gap-3">
93	          <Link href="/register" className="btn-primary px-6 py-3 text-base">
94	            Create your account
95	            <IconArrow size={16} />
96	          </Link>
97	          <Link href="/pricing" className="btn-secondary px-6 py-3 text-base">
98	            Compare plans
99	          </Link>
100	        </div>
101	      </div>
102	    </Reveal>
103	  );
104	}
