1	"use client";
2	
3	import { useState } from "react";
4	import Link from "next/link";
5	import { orderHostingAccount, retryHostingProvision, type HostingAccountView } from "@/lib/actions-hosting";
6	import { Badge, EmptyState, StatusDot, fmtMoney } from "@/components/ui/primitives";
7	import { recommendHostingPlan } from "@/lib/hosting/recommend";
8	
9	type PlanView = {
10	  id: string;
11	  name: string;
12	  priceCents: number;
13	  diskGB: number;
14	  maxSites: number;
15	  maxDatabases: number;
16	  bandwidthTB: number;
17	  mailboxes: number;
18	  freeMigration: boolean;
19	  featured: boolean;
20	  tagline: string;
21	};
22	
23	export function HostingClient({ plans, accounts }: { plans: PlanView[]; accounts: HostingAccountView[] }) {
24	  const [domain, setDomain] = useState("");
25	  const [planId, setPlanId] = useState(plans[0]?.id ?? "");
26	  const [busy, setBusy] = useState(false);
27	  const [error, setError] = useState("");
28	  const [ok, setOk] = useState("");
29	
30	  async function order() {
31	    if (!planId || !domain.trim()) return;
32	    setBusy(true);
33	    setError("");
34	    setOk("");
35	    try {
36	      const res = await orderHostingAccount(planId, domain.trim());
37	      if (res.error) setError(res.error);
38	      else {
39	        setOk("Account created — it’s being set up now.");
40	        setDomain("");
41	        setTimeout(() => window.location.reload(), 900);
42	      }
43	    } catch {
44	      setError("Something went wrong. Your wallet was not charged — try again.");
45	    } finally {
46	      setBusy(false);
47	    }
48	  }
49	
50	  async function retry(id: string) {
51	    await retryHostingProvision(id);
52	    window.location.reload();
53	  }
54	
55	  return (
56	    <div className="space-y-8">
57	      <div>
58	        <h1 className="text-xl font-semibold">Web Hosting</h1>
59	        <p className="mt-1 text-sm text-slate-400">
60	          Host your website without managing a server — we run PHP, databases, email and SSL for you. Point your
61	          domain at us and you’re live.
62	        </p>
63	      </div>
64	
65	      {/* Your accounts — compact cards linking to the per-account dashboard. */}
66	      {accounts.length > 0 ? (
67	        <div className="space-y-4">
68	          <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">Your hosting accounts</h2>
69	          <div className="grid gap-3 sm:grid-cols-2">
70	            {accounts.map((a) => (
71	              <AccountCard key={a.id} a={a} onRetry={() => retry(a.id)} />
72	            ))}
73	          </div>
74	        </div>
75	      ) : (
76	        <EmptyState
77	          title="No hosting accounts yet"
78	          sub="Pick a plan below, enter your domain, and we’ll set up an isolated hosting account for you in a minute."
79	        />
80	      )}
81	
82	      {/* Order a (new) site. */}
83	      <div className="card">
84	        <h2 className="mb-1 font-semibold">{accounts.length ? "Host another site" : "Host a new site"}</h2>
85	        <p className="mb-3 text-xs text-slate-500">Each site gets its own isolated account, storage quota and databases.</p>
86	        {error && <div className="mb-3 rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">{error}</div>}
87	        {ok && <div className="mb-3 rounded-xl border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">{ok}</div>}
88	        {plans.length === 0 ? (
89	          <p className="text-sm text-slate-400">No hosting plans are available yet. Check back soon.</p>
90	        ) : (
91	          <>
92	            <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
93	              {plans.map((p) => {
94	                const rec = recommendHostingPlan(p);
95	                const selected = planId === p.id;
96	                return (
97	                  <button
98	                    key={p.id}
99	                    type="button"
100	                    onClick={() => setPlanId(p.id)}
101	                    className={`relative flex flex-col rounded-xl border px-4 py-3 text-left transition ${
102	                      selected ? "border-brand-400 bg-brand-500/10" : p.featured ? "border-brand-500/40 hover:border-brand-400" : "border-white/10 hover:border-white/20"
103	                    }`}
104	                  >
105	                    {p.featured && (
106	                      <span className="absolute -top-2 right-3 rounded-full bg-brand-500 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-white">
107	                        Most popular
108	                      </span>
109	                    )}
110	                    <div className="flex items-baseline justify-between">
111	                      <span className="font-medium">{p.name}</span>
112	                      <span className="text-sm font-semibold">
113	                        {fmtMoney(p.priceCents)}
114	                        <span className="text-xs text-slate-500">/mo</span>
115	                      </span>
116	                    </div>
117	                    <p className="mt-1.5 text-xs font-medium text-brand-200">{p.tagline || rec.headline}</p>
118	                    <ul className="mt-2 space-y-0.5 text-xs text-slate-400">
119	                      <li>{p.diskGB} GB NVMe SSD storage</li>
120	                      <li>{p.maxSites} website{p.maxSites === 1 ? "" : "s"}</li>
121	                      <li>{p.maxDatabases} database{p.maxDatabases === 1 ? "" : "s"}</li>
122	                      <li>{p.bandwidthTB} TB bandwidth</li>
123	                      <li>{p.mailboxes} email mailbox{p.mailboxes === 1 ? "" : "es"} · free SSL</li>
124	                      {p.freeMigration && <li className="text-emerald-300/90">✓ Free website migration</li>}
125	                    </ul>
126	                    <p className="mt-2 text-[11px] leading-snug text-slate-500">{rec.detail}</p>
127	                  </button>
128	                );
129	              })}
130	            </div>
131	            <div className="mt-4 flex flex-wrap items-end gap-3">
132	              <div className="min-w-[220px] flex-1">
133	                <label className="label">Your domain</label>
134	                <input className="input" placeholder="example.com" value={domain} onChange={(e) => setDomain(e.target.value)} />
135	              </div>
136	              <button className="btn-primary" disabled={busy || !planId || !domain.trim()} onClick={order}>
137	                {busy ? "Creating…" : "Create account"}
138	              </button>
139	            </div>
140	            <p className="mt-2 text-xs text-slate-500">
141	              Charged from your wallet. You don’t need to move your domain yet — you’ll get the exact DNS record to set
142	              after it’s created.
143	            </p>
144	          </>
145	        )}
146	      </div>
147	    </div>
148	  );
149	}
150	
151	/* ---------------------------------------------------------------- card --- */
152	
153	function AccountCard({ a, onRetry }: { a: HostingAccountView; onRetry: () => void }) {
154	  const diskGB = Math.round(a.diskQuotaMB / 1024);
155	  const storage = a.diskUsedMB != null ? `${(a.diskUsedMB / 1024).toFixed(a.diskUsedMB < 1024 ? 2 : 1)} / ${diskGB} GB` : `${diskGB} GB`;
156	
157	  const body = (
158	    <>
159	      <div className="flex items-start justify-between gap-2">
160	        <div className="min-w-0">
161	          <p className="truncate font-medium text-slate-100">{a.primaryDomain}</p>
162	          <p className="mt-0.5 text-xs text-slate-500">{a.planName} · PHP {a.phpVersion}</p>
163	        </div>
164	        <StatusDot status={a.status} />
165	      </div>
166	      <div className="mt-3 flex flex-wrap items-center gap-2 text-[11px] text-slate-400">
167	        <span className="rounded-md border border-white/[0.06] bg-white/[0.02] px-2 py-0.5">Storage {storage}</span>
168	        <span className="rounded-md border border-white/[0.06] bg-white/[0.02] px-2 py-0.5">{a.maxSites} extra site{a.maxSites === 1 ? "" : "s"}</span>
169	        <span className="rounded-md border border-white/[0.06] bg-white/[0.02] px-2 py-0.5">{a.maxDatabases} DB{a.maxDatabases === 1 ? "" : "s"}</span>
170	        {a.sslActive && <Badge tone="green">HTTPS</Badge>}
171	      </div>
172	    </>
173	  );
174	
175	  // A failed account can't be opened usefully — show the retry affordance inline.
176	  if (a.status === "FAILED") {
177	    return (
178	      <div className="card">
179	        {body}
180	        <div className="mt-3 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-300">
181	          Setup failed{a.error ? `: ${a.error}` : ""}.{" "}
182	          <button className="font-medium underline" onClick={onRetry}>Retry setup</button>
183	        </div>
184	      </div>
185	    );
186	  }
187	
188	  return (
189	    <Link href={`/dashboard/hosting/${a.id}`} className="card card-hover block transition">
190	      {body}
191	      <p className="mt-3 text-xs font-medium text-brand-300">Manage →</p>
192	    </Link>
193	  );
194	}
