1	import Link from "next/link";
2	import { Reveal } from "./Reveal";
3	import { Section, SectionTitle, PageHero } from "./primitives";
4	import { CtaBand } from "./sections";
5	import { PricingGrid, type PlanCard } from "./PricingGrid";
6	import { FaqJsonLd, ProductJsonLd } from "./StructuredData";
7	
8	/**
9	 * Shared shell for high-intent "host X on a VPS" use-case landing pages.
10	 *
11	 * The layout is consistent (premium, converts); the SUBSTANCE — intro prose,
12	 * why-points, deploy steps, FAQ — comes entirely from per-page `content`, so
13	 * every page is genuinely unique (not a thin/doorway template). Real plans feed
14	 * the pricing grid and the Product rich-result. Each page is a server component
15	 * that fetches `db.plan` and passes it here.
16	 */
17	export type UseCaseContent = {
18	  eyebrow: string;
19	  /** H1 lead-in (rendered plain) + the gradient highlight word/phrase. */
20	  title: string;
21	  highlight: string;
22	  sub: string;
23	  /** 1–3 short paragraphs of unique, specific prose. */
24	  intro: string[];
25	  /** Section title for the value props, e.g. "Built for Minecraft servers". */
26	  whyTitle: string;
27	  why: { title: string; body: string }[];
28	  /** 3–5 concrete steps to deploy X on the server. */
29	  steps: { title: string; body: string }[];
30	  /** Optional sizing hint shown above the plans. */
31	  specNote?: string;
32	  faq: { q: string; a: string }[];
33	  /** Internal links to related pages (crawl + authority flow). */
34	  related?: { label: string; href: string }[];
35	};
36	
37	export function UseCaseLanding({
38	  content,
39	  plans,
40	}: {
41	  content: UseCaseContent;
42	  plans: PlanCard[];
43	}) {
44	  return (
45	    <>
46	      <FaqJsonLd items={content.faq} />
47	      {plans.length > 0 && <ProductJsonLd plans={plans} />}
48	
